import subprocess

def t(find, inp, flags=None):
    args=['./executable']
    if flags is not None:
        args+=['--flags', flags]
    args+=[find,'X']
    p=subprocess.run(args, input=inp, capture_output=True)
    return p.stdout

def is_on(flags):
    return t('^a', b'a\nb\na', flags=flags) == b'X\nb\nX'

# Let's test more systematic to deduce rule for multiline:
# Hypothesis: multiline logic = default True, but if flags contains 'e' or 'w' => False, else if contains 's' and not contains 'm' => False, else True.
# Check this hypothesis against observed.

def predicted(flags):
    s = flags if flags is not None else ''
    if 'e' in s: return False
    if 'w' in s: return False
    if 's' in s and 'm' not in s:
        return False
    # otherwise True (including default, c,i,m, etc)
    # But what about 'm' with 'e' already handled, 'm' with 'w' already handles
    return True

# Test hypothesis against observed for all flags we tested
test_cases = ['','c','i','m','e','s','w','ms','sm','mw','wm','me','em','mm','ee','cs','sc','is','si','mcs','scm','cms','csm','mse','sem','esm','sme','mes','ems','mwcs','csmw','wms','smw','mws','wsm','s','cs','sc','is','si','ss','sss','css','scs','csc','iss','ssi','ms','sm','mcs','cms','scm','csm','ims','sim','mis','smi','mss','sms','mssc','csms','smm','mms','mmm','m','e','me','em','mme','eem','mem','eme','meme','emem','mm','ee','mcs','scm','cms','cism','mics']
for flags in test_cases:
    actual = is_on(flags)
    pred = predicted(flags)
    if actual != pred:
        print(f"MISMATCH {flags!r} actual {'on' if actual else 'off'} pred {'on' if pred else 'off'}")
    else:
        # print match
        pass

print("hypothesis test done")

# Test additional edge: flags with 's' and 'm' plus maybe c/i should still be on (we saw mcs on, cms on etc)
for flags in ['s','ms','sm','smm','mms','sms','mss','cmss','scms','mcss']:
    print(flags, is_on(flags), predicted(flags))

# Check w dominance: any flag containing w should be off per hypothesis. Let's verify with earlier data: 'w' off, 'mw' off, 'cmw' off, 'wcm' off, 'mwc' off, 'wms' off etc all off matches. But what about 'w' with 'm' and 's'? 'mws' off matches. Good.
# Check e dominance: any containing e should be off. We saw 'me','em','mme','eem' etc all off. But what about 'e' alone off yes.
# What about flag containing both m and s but also e? 'mse' we saw off (since e). Good.
# So hypothesis holds for tested.

# Now we need also handle dotall and word flags.
# Let's test dotall prediction: dotall True if flags contains 's' . Let's verify.
def is_dotall(flags):
    return t('a.*b', b'a\nb', flags=flags) == b'X'

def pred_dotall(flags):
    return 's' in (flags or '')

for flags in ['','c','i','m','e','s','w','ms','sm','mw','wm','cs','sc','is','si','mcs','cms','scm','csm','se','es','ws','sw','s','ms','sm','m','mcs','scm']:
    actual = is_dotall(flags)
    pred = pred_dotall(flags)
    if actual != pred:
        print(f"dotall mismatch {flags!r} actual {actual} pred {pred}")

print("dotall test done")

# Word flag: w True if flags contains 'w' . Test earlier: 'hello' with w gave whole word only.
def is_word(flags):
    return t('hello', b'hello helloworld', flags=flags) == b'X helloworld'

def pred_word(flags):
    return 'w' in (flags or '')

for flags in ['','c','i','m','e','s','w','ms','sm','mw','wm','cs','sc','is','si','mcs','cms','scm','csm','wc','cw','mw','wm','w','wz','zw','mwc','cwm']:
    actual = is_word(flags)
    pred = pred_word(flags)
    if actual != pred:
        print(f"word mismatch {flags!r} actual {actual} pred {pred} out {t('hello', b'hello helloworld', flags=flags)!r}")

print("word test done")

# Case-insensitive predicted as last occurrence rule we already established. Let's formalize: default False, scan left to right, last c/i determines.
def pred_ci(flags):
    s = flags or ''
    last = None
    for ch in s:
        if ch == 'c': last = False
        elif ch == 'i': last = True
    return last if last is not None else False

for flags in ['','c','i','ci','ic','csi','cis','sic','sci','ics','isc','cmi','cim','mic','mci','imc','icm','mcs','scm','cms','cism','mics','m','mi','mc','im','cm','cs','sc','is','si']:
    actual = t('hello', b'Hello', flags=flags) == b'X'
    pred = pred_ci(flags)
    if actual != pred:
        print(f"ci mismatch {flags!r} actual {actual} pred {pred}")

print("ci test done")
