  -f, --flags <FLAGS>             Regex flags. May be combined (like `-f mc`).
  -h, --help                      Print help (see more with '--help')
  -V, --version                   Print version
"""

def unescape_find(s):
    res=[]
    i=0
    L=len(s)
    while i<L:
        if s[i]=='\\' and i+1<L:
            nxt=s[i+1]
            if nxt=='n':
                res.append('\n'); i+=2; continue
            elif nxt=='t':
                res.append('\t'); i+=2; continue
            elif nxt=='r':
                res.append('\r'); i+=2; continue
            elif nxt=='\\':
                res.append('\\'); i+=2; continue
            elif nxt=='a':
                res.append('\x07'); i+=2; continue
            elif nxt=='f':
                res.append('\x0c'); i+=2; continue
            elif nxt=='v':
                res.append('\x0b'); i+=2; continue
            else:
                res.append('\\'); i+=1; continue
        else:
            res.append(s[i]); i+=1
    return ''.join(res)

def unescape_replace(s):
    res=[]
    i=0
    L=len(s)
    while i<L:
        if s[i]=='\\' and i+1<L:
            nxt=s[i+1]
            if nxt=='n':
                res.append('\n'); i+=2; continue
            elif nxt=='t':
                res.append('\t'); i+=2; continue
            elif nxt=='r':
                res.append('\r'); i+=2; continue
            elif nxt=='\\':
                res.append('\\'); i+=2; continue
            else:
                res.append(s[i]); i+=1; continue
        else:
            res.append(s[i]); i+=1
    return ''.join(res)

def parse_args(argv):
    preview=False
    fixed=False
    maxrep=0
    flags=None
    flags_set=False
    find=None
    replace=None
    files=[]
    end_of_options=False
    i=1
    n=len(argv)
    def err(msg):
        sys.stderr.write(msg)
        if not msg.endswith('\n'):
            sys.stderr.write('\n')
        sys.exit(2)
    while i<n:
        arg=argv[i]
        if end_of_options:
            if find is None:
                find=arg
            elif replace is None:
                replace=arg
            else:
                files.append(arg)
            i+=1
            continue
        if arg=='--':
            end_of_options=True
            i+=1
            continue
        if arg.startswith('--'):
            if '=' in arg:
                name,val=arg.split('=',1)
                has_val=True
            else:
                name=arg
                val=None
                has_val=False
            if name=='--preview':
                if has_val:
                    err(f"error: unexpected value '{val}' for '--preview' found; no value was expected")
                preview=True
                i+=1
                continue
            elif name=='--fixed-strings':
                if has_val:
                    err(f"error: unexpected value '{val}' for '--fixed-strings' found; no value was expected")
                fixed=True
                i+=1
                continue
            elif name=='--help':
                if has_val:
                    err(f"error: unexpected value '{val}' for '--help' found; no value was expected")
                sys.stdout.write(HELP_LONG)
                sys.exit(0)
            elif name=='--version':
                if has_val:
                    err(f"error: unexpected value '{val}' for '--version' found; no value was expected")
                sys.stdout.write(VERSION+"\n")
                sys.exit(0)
            elif name=='--max-replacements':
                if not has_val:
                    if i+1 >= n:
                        err("error: a value is required for '--max-replacements <LIMIT>' but none was supplied\n\nFor more information, try '--help'.")
                    nxt=argv[i+1]
                    if nxt.startswith('-'):
                        err(f"error: unexpected argument '{nxt}' found\n\n  tip: to pass '{nxt}' as a value, use '-- {nxt}'\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.")
                    val=nxt
                    i+=2
                else:
                    i+=1
                if not val.isdigit():
                    sys.stderr.write(f"error: invalid value '{val}' for '--max-replacements <LIMIT>': invalid digit found in string\n\nFor more information, try '--help'.\n")
                    sys.exit(2)
