        sys.exit(2)
    return preview, fixed, maxrep, flags, find, replace, files

def main():
    preview, fixed, maxrep, flags, find_raw, replace_raw, files = parse_args(sys.argv)

    # Unescape FIND and REPLACE
    if fixed:
        find_pat = find_raw
        replace_pat = replace_raw
    else:
        find_pat = unescape_find(find_raw)
        replace_pat = unescape_replace(replace_raw)

    # Determine flags interpretation
    # Default values: case_sensitive true (i.e., not insensitive), multiline true, dot false, word false
    # But we have complex logic as per observed
    flags_str = flags if flags is not None else ""
    # For regex mode, build options; for fixed, we still need case and word
    # Compute case_insensitive: last c/i wins, default false (case-sensitive)
    case_insensitive = False
    last_ci = None
    for ch in flags_str:
        if ch=='c':
            last_ci=False
        elif ch=='i':
            last_ci=True
    if last_ci is not None:
        case_insensitive = last_ci
    # For fixed mode, we still use case_insensitive for literal search
    # For regex mode, also need multiline, dotall, word
    # multiline logic
    def multiline_enabled(flags_str):
        s=flags_str
        if 'e' in s:
            return False
        if 'w' in s:
            return False
        if 's' in s and 'm' not in s:
            return False
        return True
    multiline = multiline_enabled(flags_str)
    # dotall logic: last s/w wins
    dotall = False
    last_dot = None
    for ch in flags_str:
        if ch=='s':
            last_dot=True
        elif ch=='w':
            last_dot=False
    if last_dot is not None:
        dotall = last_dot
    else:
        dotall = False
    word = 'w' in flags_str

    # Build regex or fixed processor
    # For fixed, we will use literal search
    # For regex, compile pattern
    pattern = None
    regex_flags = 0
    if not fixed:
        # prepare pattern for regex
        pat = find_pat
        if word:
            # wrap with word boundaries
            # Use non-capturing group
            pat = r'\b(?:' + pat + r')\b'
        # Build re flags
        if case_insensitive:
            regex_flags |= re.IGNORECASE
        if multiline:
            regex_flags |= re.MULTILINE
        if dotall:
            regex_flags |= re.DOTALL
        try:
            pattern = re.compile(pat, flags=regex_flags)
        except re.error as e:
            sys.stderr.write(f"error: invalid regex {e}\n")
            sys.exit(1)
    else:
        # fixed: literal pattern already in find_pat, but case_insensitive and word affect matching
        # We won't compile regex for fixed; we'll handle manually
        pass

    # Replacement handling: need function to expand captures for regex mode
    # For fixed mode, replacement is literal (no expansion, no unescaping beyond what we already did? For fixed we didn't unescape, so replace_pat is literal)

    # Define replacement expansion for regex
    def expand_replacement(match, repl):
        # repl is unescaped_replace string
        # Need to handle $$, $1, $name, ${1}, ${name}
        res=[]
        i=0
        L=len(repl)
        while i<L:
            if repl[i]=='$' and i+1<L and repl[i+1]=='$':
                res.append('$')
                i+=2
            elif repl[i]=='$' and i+1<L and repl[i+1]=='{':
                # find closing }
                end = repl.find('}', i+2)
