    L=len(s)
    while i<L:
        if s[i]=='\\' and i+1<L:
            nxt=s[i+1]
            if nxt=='n':
                res.append('\n'); i+=2; continue
            elif nxt=='t':
                res.append('\t'); i+=2; continue
            elif nxt=='r':
                res.append('\r'); i+=2; continue
            elif nxt=='\\':
                res.append('\\'); i+=2; continue
            elif nxt=='a':
                res.append('\x07'); i+=2; continue
            elif nxt=='f':
                res.append('\x0c'); i+=2; continue
            elif nxt=='v':
                res.append('\x0b'); i+=2; continue
            else:
                res.append('\\'); i+=1; continue
        else:
            res.append(s[i]); i+=1
    return ''.join(res)

def unescape_replace(s):
    res=[]
    i=0
    L=len(s)
    while i<L:
        if s[i]=='\\' and i+1<L:
            nxt=s[i+1]
            if nxt=='n':
                res.append('\n'); i+=2; continue
            elif nxt=='t':
                res.append('\t'); i+=2; continue
            elif nxt=='r':
                res.append('\r'); i+=2; continue
            elif nxt=='\\':
                res.append('\\'); i+=2; continue
            else:
                res.append(s[i]); i+=1; continue
        else:
            res.append(s[i]); i+=1
    return ''.join(res)

def validate_replacement_ambiguous(repl_raw):
    L=len(repl_raw)
    i=0
    while i<L:
        if repl_raw[i]=='$' and i+1<L and repl_raw[i+1]=='$':
            i+=2
            continue
        elif repl_raw[i]=='$':
            if i+1<L and repl_raw[i+1]=='{':
                end = repl_raw.find('}', i+2)
                if end != -1:
                    i = end+1
                    continue
                else:
                    i+=1
                    continue
            j=i+1
            if j<L and repl_raw[j].isdigit():
                k=j
                while k<L and repl_raw[k].isdigit():
                    k+=1
                if k<L and (repl_raw[k].isalnum() or repl_raw[k]=='_'):
                    digits = repl_raw[j:k]
                    m=k
                    while m<L and (repl_raw[m].isalnum() or repl_raw[m]=='_'):
                        m+=1
                    ident = repl_raw[j:m]
                    suffix = ident[len(digits):]
                    hint = f"${{{digits}}}{suffix}"
                    sys.stderr.write(f"error: The numbered capture group `${digits}` in the replacement text is ambiguous.\n")
                    sys.stderr.write(f"hint: Use curly braces to disambiguate it `{hint}`.\n")
                    sys.stderr.write(repl_raw+"\n")
                    spaces = " " * (i+1)
                    carets = "^" * len(ident)
                    sys.stderr.write(spaces+carets+"\n")
                    sys.exit(1)
                else:
                    i = k
                    continue
            if j<L and (repl_raw[j].isalpha() or repl_raw[j]=='_'):
                k=j
                while k<L and (repl_raw[k].isalnum() or repl_raw[k]=='_'):
                    k+=1
                i=k
                continue
            i+=1
            continue
        else:
            i+=1

def parse_args(argv):
    preview=False
    fixed=False
    maxrep=0
    flags=None
    flags_set=False
    find=None
    replace=None
    files=[]
    end_of_options=False
    i=1
    n=len(argv)
    def err(msg):
        sys.stderr.write(msg)
        if not msg.endswith('\n'):
            sys.stderr.write('\n')
        sys.exit(2)
    while i<n:
        arg=argv[i]
        if end_of_options:
            if find is None:
                find=arg
            elif replace is None:
                replace=arg
            else:
                files.append(arg)
            i+=1
            continue
        if arg=='--':
            end_of_options=True
            i+=1
            continue
        if arg.startswith('--'):
            if '=' in arg:
                name,val=arg.split('=',1)
                has_val=True
            else:
                name=arg
                val=None
                has_val=False
            if name=='--preview':
                if has_val:
                    err(f"error: unexpected value '{val}' for '--preview' found; no value was expected")
                preview=True
                i+=1
                continue
            elif name=='--fixed-strings':
                if has_val:
                    err(f"error: unexpected value '{val}' for '--fixed-strings' found; no value was expected")
                fixed=True
                i+=1
                continue
            elif name=='--help':
                if has_val:
                    err(f"error: unexpected value '{val}' for '--help' found; no value was expected")
                sys.stdout.write(HELP_LONG)
                sys.exit(0)
            elif name=='--version':
                if has_val:
                    err(f"error: unexpected value '{val}' for '--version' found; no value was expected")
                sys.stdout.write(VERSION+"\n")
                sys.exit(0)
            elif name=='--max-replacements':
                if not has_val:
                    if i+1 >= n:
                        err("error: a value is required for '--max-replacements <LIMIT>' but none was supplied\n\nFor more information, try '--help'.")
                    nxt=argv[i+1]
                    if nxt.startswith('-'):
                        err(f"error: unexpected argument '{nxt}' found\n\n  tip: to pass '{nxt}' as a value, use '-- {nxt}'\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.")
                    val=nxt
                    i+=2
                else:
                    i+=1
                if not val.isdigit():
                    sys.stderr.write(f"error: invalid value '{val}' for '--max-replacements <LIMIT>': invalid digit found in string\n\nFor more information, try '--help'.\n")
                    sys.exit(2)
                maxrep=int(val)
                continue
            elif name=='--flags':
                if not has_val:
                    if i+1 >= n:
                        err("error: a value is required for '--flags <FLAGS>' but none was supplied\n\nFor more information, try '--help'.")
                    nxt=argv[i+1]
                    if nxt.startswith('-'):
                        err(f"error: unexpected argument '{nxt}' found\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.")
                    val=nxt
                    i+=2
                else:
                    i+=1
                if flags_set:
                    sys.stderr.write("error: the argument '--flags <FLAGS>' cannot be used multiple times\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
                    sys.exit(2)
                flags=val
                flags_set=True
                continue
            else:
                err(f"error: unexpected argument '{arg}' found\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.")
        elif arg.startswith('-') and len(arg)>1:
            j=1
            consumed=False
            val_for=None
            typ=None
            from_next=False
            while j < len(arg):
                ch=arg[j]
                if ch=='p':
                    preview=True
                    j+=1
                elif ch=='F':
                    fixed=True
                    j+=1
                elif ch=='h':
                    sys.stdout.write(HELP_SHORT)
                    sys.exit(0)
                elif ch=='V':
                    sys.stdout.write(VERSION+"\n")
                    sys.exit(0)
                elif ch=='n':
                    if j+1 < len(arg):
                        rest=arg[j+1:]
                        if rest.startswith('='):
                            val_for=rest[1:]
                        else:
                            val_for=rest
                        typ='n'
                        consumed=True
                        from_next=False
                        j=len(arg)
                        break
                    else:
                        if i+1 >= n:
                            err("error: a value is required for '--max-replacements <LIMIT>' but none was supplied\n\nFor more information, try '--help'.")
                        nxt=argv[i+1]
                        if nxt.startswith('-'):
                            sys.stderr.write(f"error: unexpected argument '{nxt}' found\n\n  tip: to pass '{nxt}' as a value, use '-- {nxt}'\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
                            sys.exit(2)
                        val_for=nxt
                        typ='n'
                        consumed=True
                        from_next=True
                        j=len(arg)
                        break
                elif ch=='f':
                    if j+1 < len(arg):
                        rest=arg[j+1:]
                        if rest.startswith('='):
                            val_for=rest[1:]
                        else:
                            val_for=rest
                        typ='f'
                        consumed=True
                        from_next=False
                        j=len(arg)
                        break
                    else:
                        if i+1 >= n:
                            err("error: a value is required for '--flags <FLAGS>' but none was supplied\n\nFor more information, try '--help'.")
                        nxt=argv[i+1]
                        if flags_set:
                            sys.stderr.write("error: the argument '--flags <FLAGS>' cannot be used multiple times\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
                            sys.exit(2)
                        if nxt.startswith('-'):
                            err(f"error: unexpected argument '{nxt}' found\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.")
                        val_for=nxt
                        typ='f'
                        consumed=True
                        from_next=True
                        j=len(arg)
                        break
                else:
                    err(f"error: unexpected argument '-{ch}' found\n\n  tip: to pass '-{ch}' as a value, use '-- -{ch}'\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.")
            if consumed:
                if typ=='n':
                    if not val_for.isdigit():
                        sys.stderr.write(f"error: invalid value '{val_for}' for '--max-replacements <LIMIT>': invalid digit found in string\n\nFor more information, try '--help'.\n")
                        sys.exit(2)
                    maxrep=int(val_for)
                    if from_next:
                        i+=2
                    else:
                        i+=1
                    continue
                else:
                    if flags_set:
                        sys.stderr.write("error: the argument '--flags <FLAGS>' cannot be used multiple times\n\nUsage: executable [OPTIONS] <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
                        sys.exit(2)
                    flags=val_for
                    flags_set=True
                    if from_next:
                        i+=2
                    else:
                        i+=1
                    continue
            else:
                i+=1
            continue
        else:
            if find is None:
                find=arg
            elif replace is None:
                replace=arg
            else:
                files.append(arg)
            i+=1
            continue
    if find is None:
        sys.stderr.write("error: the following required arguments were not provided:\n  <FIND>\n  <REPLACE_WITH>\n\nUsage: executable <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
        sys.exit(2)
    if replace is None:
        sys.stderr.write("error: the following required arguments were not provided:\n  <REPLACE_WITH>\n\nUsage: executable <FIND> <REPLACE_WITH> [FILES]...\n\nFor more information, try '--help'.\n")
        sys.exit(2)
    return preview, fixed, maxrep, flags, find, replace, files

def main():
    preview, fixed, maxrep, flags, find_raw, replace_raw, files = parse_args(sys.argv)
    if not fixed:
        validate_replacement_ambiguous(replace_raw)
    if fixed:
        find_pat = find_raw
        replace_pat = replace_raw
    else:
        find_pat = unescape_find(find_raw)
        replace_pat = unescape_replace(replace_raw)
    flags_str = flags if flags is not None else ""
    case_insensitive=False
    last_ci=None
    for ch in flags_str:
        if ch=='c':
            last_ci=False
        elif ch=='i':
            last_ci=True
    if last_ci is not None:
        case_insensitive=last_ci
    def multiline_enabled(s):
        if 'e' in s:
            return False
        if 'w' in s:
            return False
        if 's' in s and 'm' not in s:
            return False
        return True
    multiline = multiline_enabled(flags_str)
    dotall=False
    last_dot=None
    for ch in flags_str:
        if ch=='s':
            last_dot=True
        elif ch=='w':
            last_dot=False
    if last_dot is not None:
        dotall=last_dot
    word = 'w' in flags_str
    pattern=None
    if not fixed:
        pat = find_pat
        if word:
            pat = r'\b(?:' + pat + r')\b'
        regex_flags=0
        if case_insensitive:
            regex_flags|=re.IGNORECASE
        if multiline:
            regex_flags|=re.MULTILINE
        if dotall:
            regex_flags|=re.DOTALL
        try:
            pattern=re.compile(pat, flags=regex_flags)
        except re.error as e:
            sys.stderr.write(f"error: invalid regex {e}\n")
            sys.exit(1)
    def expand_replacement(match, repl):
        res=[]
        i=0
        L=len(repl)
        while i<L:
            if repl[i]=='$' and i+1<L and repl[i+1]=='$':
                res.append('$')
                i+=2
            elif repl[i]=='$' and i+1<L and repl[i+1]=='{':
                end=repl.find('}', i+2)
                if end==-1:
                    res.append(repl[i])
                    i+=1
                else:
                    name=repl[i+2:end]
                    val=None
                    if name.isdigit():
                        try:
                            idx=int(name)
                            if idx==0:
                                val=match.group(0)
                            else:
                                try:
                                    val=match.group(idx)
                                except IndexError:
                                    val=''
                                if val is None:
                                    val=''
                        except:
                            val=''
                    else:
                        try:
                            val=match.group(name)
                        except IndexError:
                            val=''
                        except re.error:
                            val=''
                        if val is None:
                            val=''
                    if val is None:
                        val=''
                    res.append(val)
                    i=end+1
            elif repl[i]=='$':
                j=i+1
                while j<L and (repl[j].isalnum() or repl[j]=='_'):
                    j+=1
                ident=repl[i+1:j]
                if ident=='':
                    res.append('$')
                    i+=1
                else:
                    val=None
                    if ident.isdigit():
                        try:
                            idx=int(ident)
                            if idx==0:
                                val=match.group(0)
                            else:
                                try:
                                    val=match.group(idx)
                                except IndexError:
                                    val=''
                                if val is None:
                                    val=''
                        except:
                            val=''
                    else:
                        try:
                            val=match.group(ident)
                        except IndexError:
                            val=''
                        except re.error:
                            val=''
                        if val is None:
                            val=''
                    if val is None:
                        val=''
                    res.append(val)
                    i=j
            else:
                res.append(repl[i])
                i+=1
        return ''.join(res)
    def process_text(text):
        if fixed:
            pat = re.escape(find_pat)
            if word:
                pat = r'\b(?:' + pat + r')\b'
            flags_re=0
            if case_insensitive:
                flags_re|=re.IGNORECASE
            try:
                rx=re.compile(pat, flags=flags_re)
            except re.error as e:
                sys.stderr.write(f"error: invalid regex {e}\n")
                sys.exit(1)
            cnt=0 if maxrep==0 else maxrep
            if cnt==0:
                return rx.sub(replace_pat, text)
            else:
                return rx.sub(replace_pat, text, count=cnt)
        else:
            cnt=0 if maxrep==0 else maxrep
            def repl_func(m):
                return expand_replacement(m, replace_pat)
            if cnt==0:
                return pattern.sub(repl_func, text)
            else:
                return pattern.sub(repl_func, text, count=cnt)
    if not files:
        data=sys.stdin.buffer.read()
        try:
            text=data.decode('utf-8')
        except UnicodeDecodeError:
            text=data.decode('utf-8', errors='surrogateescape')
        result=process_text(text)
        try:
            out_bytes=result.encode('utf-8')
        except:
            out_bytes=result.encode('utf-8', errors='surrogateescape')
        sys.stdout.buffer.write(out_bytes)
    else:
        outputs=[]
        for fpath in files:
            if not os.path.exists(fpath):
                sys.stderr.write(f"error: invalid path: {fpath}\n")
                sys.exit(1)
            if not os.path.isfile(fpath):
                try:
                    with open(fpath, 'r'):
                        pass
                except IsADirectoryError:
                    sys.stderr.write(f"error: No such device (os error 19)\n")
                    sys.exit(1)
                except OSError as e:
                    sys.stderr.write(f"error: {e}\n")
                    sys.exit(1)
                sys.stderr.write(f"error: No such device (os error 19)\n")
                sys.exit(1)
            try:
                with open(fpath, 'r', encoding='utf-8', errors='surrogateescape') as f:
                    content=f.read()
            except Exception as e:
                sys.stderr.write(f"error: {e}\n")
                sys.exit(1)
            try:
                new_content=process_text(content)
            except SystemExit:
                raise
            except Exception as e:
                sys.stderr.write(f"error: invalid regex {e}\n")
                sys.exit(1)
            if preview:
                outputs.append((fpath,new_content))
            else:
                try:
                    with open(fpath, 'w', encoding='utf-8', errors='surrogateescape') as out:
                        out.write(new_content)
                except Exception as e:
                    sys.stderr.write(f"error: {e}\n")
                    sys.exit(1)
        if preview:
            if len(outputs)==1:
                fpath,new_content=outputs[0]
                sys.stdout.write(new_content)
            else:
                for fpath,new_content in outputs:
                    sys.stdout.write(f"----- FILE {fpath} -----\n")
                    sys.stdout.write(new_content)

if __name__=='__main__':
    main()
